INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8bcc-7c1a-af1d-41720b9197b5'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'Factorise completely: 6y^2 - 15y.', '3y(2y - 5)', 'Take out the common factor 3y. This gives 6y^2 - 15y = 3y(2y - 5).', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.492Z'::timestamptz, '2026-08-15T07:36:12.492Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8bdc-7410-ba31-9a3cb9aea481'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'Factorise completely: x^2 - 9x + 20.', '(x - 4)(x - 5)', 'Find two numbers whose product is 20 and sum is -9. They are -4 and -5, so the expression factorises to (x - 4)(x - 5).', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.508Z'::timestamptz, '2026-08-15T07:36:12.508Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8bef-7ab5-a104-7e114d0dc45f'::uuid, '019f9df7-a2a2-7839-8287-1e75e9dd37f8'::uuid, 'y is directly proportional to the cube root of (x + 1). It is given that x = 7 when y = 1. Find the value of y when x = 124.', '2.5', 'Let y = k∛(x + 1). When x = 7, 1 = k∛8 = 2k, so k = 1/2. When x = 124, y = 1/2 × ∛125 = 1/2 × 5 = 2.5.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.527Z'::timestamptz, '2026-08-15T07:36:12.527Z'::timestamptz) ON CONFLICT (id) DO NOTHING;